const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "mysql",
  "inlineSchema": "// Prisma 7 — La URL de conexión se gestiona desde prisma.config.ts\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nenum TipoDocumento {\n  DNI\n  CE\n  PASAPORTE\n  RUC\n}\n\nenum TipoCredito {\n  CONSUMO\n  OTROS\n}\n\n/// Tabla física: usuarios (Administrador, Supervisor, Auditor)\nmodel Usuario {\n  id_usuario        String    @id @default(uuid()) @db.VarChar(36)\n  username          String    @unique @db.VarChar(50)\n  nombres           String?   @db.VarChar(150)\n  apellidos         String?   @db.VarChar(200)\n  email             String?   @db.VarChar(150)\n  sede              String?   @db.VarChar(100)\n  // Departamento donde opera el auditor de campo (ej. \"Junín\", \"Lima\"): se compara\n  // contra expediente.departamento al asignar, para no mandarlo a visitar a otra\n  // ciudad. Nulo = sin restricción geográfica configurada todavía.\n  departamento      String?   @db.VarChar(100)\n  password_hash     String    @db.Text\n  rol               String    @db.VarChar(20) // ADMINISTRADOR, SUPERVISOR, AUDITOR\n  estado            String    @default(\"ACTIVO\") @db.VarChar(20) // ACTIVO, INACTIVO\n  fecha_creacion    DateTime  @default(now())\n  mfa_habilitado    Boolean   @default(false)\n  mfa_requerido     Boolean   @default(false)\n  mfa_exento        Boolean   @default(false)\n  mfa_secreto       String?   @db.Text\n  mfa_ultimo_uso    DateTime?\n  token_version     Int       @default(0)\n  intentos_fallidos Int       @default(0)\n  bloqueado_hasta   DateTime?\n  ultimo_acceso     DateTime?\n  password_cambio   DateTime  @default(now())\n  latitud           Decimal?  @db.Decimal(10, 8) // última ubicación conocida en campo (auditor/supervisor)\n  longitud          Decimal?  @db.Decimal(11, 8)\n\n  asignaciones AsignacionAuditoria[]\n  visitas      VisitaAuditoria[]\n  dispositivos DispositivoAutorizado[]\n  trackings    TrackingUbicacion[]\n\n  @@map(\"usuarios\")\n}\n\n/// Historial de posiciones GPS del personal de campo (Supervisor/Auditor) — permite\n/// reconstruir la ruta recorrida en el mapa de supervisión (Fase 2/Fase 6 del flujo).\nmodel TrackingUbicacion {\n  id_tracking      BigInt   @id @default(autoincrement())\n  id_usuario       String   @db.VarChar(36)\n  latitud          Decimal  @db.Decimal(10, 8)\n  longitud         Decimal  @db.Decimal(11, 8)\n  precision_metros Decimal? @db.Decimal(8, 2)\n  registrado_en    DateTime @default(now())\n\n  usuario Usuario @relation(fields: [id_usuario], references: [id_usuario], onDelete: Restrict, onUpdate: Cascade)\n\n  @@index([id_usuario, registrado_en])\n  @@map(\"tracking_ubicacion\")\n}\n\n/// Tabla física: dispositivos_autorizados — vincula un usuario a los dispositivos desde los que ha iniciado sesión\nmodel DispositivoAutorizado {\n  id_dispositivo     String    @id @default(uuid()) @db.VarChar(36)\n  id_usuario         String    @db.VarChar(36)\n  device_id          String    @db.VarChar(150) // identificador estable del dispositivo (installationId)\n  nombre_dispositivo String?   @db.VarChar(150)\n  activo             Boolean   @default(true)\n  primer_uso         DateTime  @default(now())\n  ultimo_uso         DateTime?\n\n  usuario Usuario @relation(fields: [id_usuario], references: [id_usuario], onDelete: Restrict, onUpdate: Cascade)\n\n  @@unique([id_usuario, device_id])\n  @@index([id_usuario])\n  @@map(\"dispositivos_autorizados\")\n}\n\n/// Tabla física: expedientes — ficha de crédito/cliente a auditar, prellenada por importación\nmodel Expediente {\n  id_expediente     Int         @id @default(autoincrement())\n  codigo_expediente String      @unique @db.VarChar(50) // N° de crédito / clave de importación\n  tipo_credito      TipoCredito @default(CONSUMO)\n  oficina           String?     @db.VarChar(100)\n\n  tipo_documento_cliente   TipoDocumento @default(DNI)\n  numero_documento_cliente String        @db.VarChar(20)\n  nombres_cliente          String        @db.VarChar(200)\n  telefono_cliente         String?       @db.VarChar(20)\n  direccion_domicilio      String?       @db.VarChar(255)\n  distrito                 String?       @db.VarChar(100)\n  provincia                String?       @db.VarChar(100)\n  departamento             String?       @db.VarChar(100)\n  latitud                  Decimal?      @db.Decimal(10, 8) // domicilio del cliente — base para el chequeo de geocerca\n  longitud                 Decimal?      @db.Decimal(11, 8)\n\n  asesor_responsable String   @db.VarChar(150)\n  monto_desembolso   Decimal? @db.Decimal(12, 2)\n  moneda             String?  @db.VarChar(5)\n\n  // Bloques variables de la ficha (ver PLANTILLAS FICHAS DE VISITA): se guardan como JSON\n  // para no sobre-normalizar ~80 campos que la app solo muestra de referencia al auditor.\n  datos_cliente         Json? // identidad/domicilio adicionales (fuente, fecha nac., edad, estado civil, vivienda...)\n  datos_negocio         Json? // actividad, antigüedad, empleador/negocio, tipo de cliente...\n  datos_credito         Json? // historial crediticio + datos del crédito y participantes\n  evaluacion_financiera Json? // ingresos / balance general / estado de resultados (variante Otros)\n  endeudamiento         Json? // tabla de endeudamiento del cliente y cónyuge\n\n  estado           String   @default(\"PENDIENTE\") @db.VarChar(20) // PENDIENTE, ASIGNADO, VISITADO, CERRADO\n  fecha_creacion   DateTime @default(now())\n  fecha_actualizar DateTime @updatedAt\n\n  asignaciones AsignacionAuditoria[]\n  visitas      VisitaAuditoria[]\n\n  @@index([latitud, longitud])\n  @@index([distrito])\n  @@index([departamento])\n  @@index([asesor_responsable])\n  @@map(\"expedientes\")\n}\n\n/// Tabla física: asignaciones_auditoria — auditor ↔ expediente (muestra a visitar)\nmodel AsignacionAuditoria {\n  id_asignacion      Int       @id @default(autoincrement())\n  id_expediente      Int\n  id_usuario_auditor String    @db.VarChar(36)\n  fecha_asignacion   DateTime  @default(now())\n  fecha_fin          DateTime?\n  estado             String    @default(\"ACTIVA\") @db.VarChar(20) // ACTIVA, FINALIZADA, CANCELADA\n  prioridad          String    @default(\"MEDIA\") @db.VarChar(20) // ALTA, MEDIA, BAJA\n\n  expediente Expediente @relation(fields: [id_expediente], references: [id_expediente], onDelete: Restrict, onUpdate: Cascade)\n  auditor    Usuario    @relation(fields: [id_usuario_auditor], references: [id_usuario], onDelete: Restrict, onUpdate: Cascade)\n\n  @@index([id_usuario_auditor])\n  @@index([id_expediente])\n  @@map(\"asignaciones_auditoria\")\n}\n\n/// Tabla física: visitas_auditoria — ejecución real de la ficha de entrevista en campo\nmodel VisitaAuditoria {\n  id_visita          Int     @id @default(autoincrement())\n  client_sync_id     String? @unique @db.VarChar(100) // idempotencia para visitas creadas sin conexión\n  id_asignacion      Int?\n  id_expediente      Int\n  id_usuario_auditor String  @db.VarChar(36)\n\n  fecha_hora_checkin  DateTime\n  fecha_hora_checkout DateTime?\n  latitud             Decimal   @db.Decimal(10, 8)\n  longitud            Decimal   @db.Decimal(11, 8)\n  precision_metros    Decimal?  @db.Decimal(8, 2) // precisión GPS reportada por el dispositivo\n\n  // Señales anti-fraude calculadas/recibidas al momento de la visita\n  distancia_domicilio_m Decimal? @db.Decimal(10, 2) // distancia Haversine vs expediente.latitud/longitud\n  mock_location         Boolean  @default(false) // ubicación simulada detectada (Fake GPS)\n  device_integrity_ok   Boolean  @default(true) // sin indicios de root/jailbreak/emulador\n  device_id             String?  @db.VarChar(150)\n  server_received_at    DateTime @default(now()) // hora del servidor, no confiar solo en la del dispositivo\n\n  resultado                String  @db.VarChar(30) // CONFORME, OBSERVADO, NO_UBICADO, RECHAZADO\n  respuestas_cuestionario  Json // preguntas SI/NO de la ficha (cuestionario al cliente)\n  comentario_negocio       String? @db.Text\n  comentario_auditor       String? @db.Text\n  otros_clientes_domicilio Json?\n  otros_ingresos           Json?\n  firma_evidencia          String? @db.Text // firma PNG en data URL\n\n  estado           String   @default(\"ABIERTA\") @db.VarChar(20) // ABIERTA, CERRADA\n  fecha_creacion   DateTime @default(now())\n  fecha_actualizar DateTime @updatedAt\n\n  expediente Expediente  @relation(fields: [id_expediente], references: [id_expediente], onDelete: Restrict, onUpdate: Cascade)\n  auditor    Usuario     @relation(fields: [id_usuario_auditor], references: [id_usuario], onDelete: Restrict, onUpdate: Cascade)\n  evidencias Evidencia[]\n\n  @@index([id_expediente])\n  @@index([id_usuario_auditor, fecha_hora_checkin])\n  @@map(\"visitas_auditoria\")\n}\n\n/// Tabla física: evidencias — fotografías/documentos de una visita\nmodel Evidencia {\n  id_evidencia     String   @id @default(uuid()) @db.VarChar(36)\n  id_visita        Int\n  tipo             String   @db.VarChar(20) // FOTO_PRINCIPAL, FOTO_ADICIONAL\n  object_key       String   @db.VarChar(255)\n  hash_sha256      String   @unique @db.VarChar(64) // detecta reuso de la misma foto entre visitas/clientes\n  latitud_captura  Decimal? @db.Decimal(10, 8)\n  longitud_captura Decimal? @db.Decimal(11, 8)\n  capturado_en     DateTime\n  fecha_creacion   DateTime @default(now())\n\n  visita VisitaAuditoria @relation(fields: [id_visita], references: [id_visita], onDelete: Restrict, onUpdate: Cascade)\n\n  @@index([id_visita])\n  @@map(\"evidencias\")\n}\n\n/// Registro inmutable de auditoría de seguridad (acceso y operaciones)\nmodel AuditoriaSeguridad {\n  id_auditoria  String   @id @default(uuid()) @db.VarChar(36)\n  fecha         DateTime @default(now())\n  request_id    String?  @db.VarChar(100)\n  actor_id      String?  @db.VarChar(36)\n  actor         String?  @db.VarChar(50)\n  rol           String?  @db.VarChar(30)\n  metodo        String   @db.VarChar(10)\n  ruta          String   @db.VarChar(255)\n  estado_http   Int\n  ip_address    String?  @db.VarChar(45)\n  ip_hash       String?  @db.VarChar(64)\n  user_agent    String?  @db.VarChar(255)\n  device_id     String?  @db.VarChar(150)\n  mock_location Boolean?\n\n  // Diff de negocio (opcional): qué entidad cambió y su estado antes/después. Lo\n  // llena el controlador vía req.auditContext cuando la operación lo amerita (no\n  // todas: un GET o un login no tienen \"entidad\" que diffear). Nunca debe contener\n  // secretos (password_hash, mfa_secreto) — cada servicio arma un snapshot sin eso.\n  entidad        String? @db.VarChar(50)\n  entidad_id     String? @db.VarChar(64)\n  valor_anterior Json?\n  valor_nuevo    Json?\n\n  @@index([fecha])\n  @@index([actor_id, fecha])\n  @@map(\"auditoria_seguridad\")\n}\n\n/// Importación masiva de expedientes por Excel (no hay integración en vivo con Caja Huancayo todavía)\nmodel ImportacionMasiva {\n  id_importacion String    @id @default(uuid()) @db.VarChar(36)\n  tipo           String    @db.VarChar(30)\n  estado         String    @default(\"PENDIENTE\") @db.VarChar(20)\n  archivo        String    @db.VarChar(255)\n  ruta_temporal  String    @db.Text\n  actor_id       String?   @db.VarChar(36)\n  total_filas    Int       @default(0)\n  procesadas     Int       @default(0)\n  insertadas     Int       @default(0)\n  actualizadas   Int       @default(0)\n  omitidas       Int       @default(0)\n  errores        Int       @default(0)\n  detalle_error  Json?\n  fecha_creacion DateTime  @default(now())\n  fecha_inicio   DateTime?\n  fecha_fin      DateTime?\n\n  @@index([estado, fecha_creacion])\n  @@index([actor_id, fecha_creacion])\n  @@map(\"importaciones_masivas\")\n}\n"
}

